-- Idempotent projection checkpoint table in PostgreSQL
CREATE TABLE projection_checkpoints (
    projection_name TEXT PRIMARY KEY,
    last_stream_pos BIGINT NOT NULL
);

-- Inside projection consumer transaction:
INSERT INTO processed_events (event_id) VALUES (:event_id) ON CONFLICT DO NOTHING;
-- Only apply read-model UPDATE if 1 row was inserted above, then advance checkpoint.
